// Expo app config (TECH-DESIGN section 12). Native config lives here, in plugins/ and in modules/;
// android/ is generated by `npx expo prebuild` and never edited by hand.
//
// APP_VARIANT=development (default): io.github.mecheng70.pitplanner.debug, "Pit Planner dev", installs beside
// the release with its own data. APP_VARIANT=production: the permanent release app ID.

import type { ConfigContext, ExpoConfig } from 'expo/config';
import pkg from './package.json';

const APP_ID = 'io.github.mecheng70.pitplanner';
const BG = '#131211'; // --bg in the mockups

export type Variant = 'development' | 'production';

export function variantOf(env: string | undefined): Variant {
  return env === 'production' ? 'production' : 'development';
}

/** 0.3.0 -> 300. Must stay above 0.2.0's 200 so the release upgrades in place. */
export function versionCode(version: string): number {
  const m = /^(\d+)\.(\d+)\.(\d+)$/.exec(version);
  if (!m) throw new Error(`package.json version must be major.minor.patch, got ${version}`);
  const [major, minor, patch] = m.slice(1).map(Number);
  if (minor > 99 || patch > 99) throw new Error(`minor and patch must be under 100, got ${version}`);
  return major * 10000 + minor * 100 + patch;
}

export default ({ config }: ConfigContext): ExpoConfig => {
  const variant = variantOf(process.env.APP_VARIANT);
  const dev = variant === 'development';
  return {
    ...config,
    name: dev ? 'Pit Planner dev' : 'Pit Planner',
    slug: 'pitplanner',
    version: pkg.version,
    scheme: 'pitplanner',
    orientation: 'portrait',
    userInterfaceStyle: 'dark',
    backgroundColor: BG,
    icon: './assets/icon-only.png',
    platforms: ['android'],
    android: {
      package: dev ? `${APP_ID}.debug` : APP_ID,
      versionCode: versionCode(pkg.version),
      adaptiveIcon: {
        foregroundImage: './assets/icon-foreground.png',
        backgroundImage: './assets/icon-background.png',
        backgroundColor: BG,
      },
      predictiveBackGestureEnabled: false,
    },
    plugins: [
      'expo-router',
      ['expo-status-bar', { style: 'light' }],
      ['expo-splash-screen', { backgroundColor: BG, image: './assets/icon-foreground.png', imageWidth: 200 }],
    ],
    experiments: { typedRoutes: true },
    extra: { variant },
  };
};
